"""QQ-获取点 的后端壳：负责菜单/搜索/存档，取值由前端虚拟解析完成。"""

from __future__ import annotations


class QQGetNode:
    """按名称读取 KJ 设置点(SetNode)的值，额外带一个启用开关。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "get_value"
    RETURN_TYPES = ("*",)
    RETURN_NAMES = ("值",)
    DESCRIPTION = (
        "按名称读取 KJ 设置点(SetNode)的值，和 KJ 获取点同机制，但多一个启用开关："
        "启用关闭时消费者视为未连接（例如一键出图的 latent_image 回退到图1分辨率）。"
        "在界面里它是虚拟节点：排队时前端把它编译成真实连线，本身不进入 prompt，"
        "所以名称下拉、开关接线都由前端扩展 web/qq_get_node.js 提供。"
        "直接走 API 提交包含它的 prompt 会报错，请在界面里使用或改用真实连线。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "名称": (
                    "STRING",
                    {"default": "", "multiline": False, "tooltip": "KJ 设置点的名称；界面里会替换成下拉框。"},
                ),
                "启用": (
                    "BOOLEAN",
                    {"default": True, "tooltip": "关闭时消费者视为未连接。"},
                ),
            },
            "optional": {
                "启用接线": (
                    "BOOLEAN",
                    {"tooltip": "可选接线口：接布尔常量（PrimitiveNode / widget 转出的口）时排队前静态读取。"},
                ),
            },
        }

    @staticmethod
    def get_value(**kwargs):
        raise RuntimeError(
            "QQ-获取点 是前端虚拟解析节点，不应该被执行；请通过 ComfyUI 界面排队，"
            "或在 API prompt 里改用真实连线。"
        )


NODE_CLASS_MAPPINGS = {"QQGetNode": QQGetNode}
NODE_DISPLAY_NAME_MAPPINGS = {"QQGetNode": "QQ-获取点"}
